
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hjs_b88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hjs_b88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.280842368604050e+00, -3.217968255748212e+00, -3.129879718354079e+00, -3.007884559603182e+00, -2.841717294209873e+00, -2.620718062706225e+00, -2.336656925240674e+00, -1.988935831789588e+00, -1.592130137086725e+00, -1.181837196193006e+00, -8.037995686066058e-01, -5.772665530471750e-01, -5.102814827305939e-01, -4.169844330184534e-01, -2.990808622850827e-01, -1.916507983034713e-01, -1.189858111191511e-01, -7.523206790459747e-02, -5.657468071166630e-02, -7.487108222160674e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


